INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 6 > Programmierung > Programme
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Programme für IT-Systeme immer in einer objektorientierten Sprache geschrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "Andere Paradigmen wie prozedural sind ebenfalls möglich"}, {"text": "Ja", "correct": false, "because": "Programmierstil ist flexibel"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Programme ohne vorherige Anforderungsanalyse erfolgreich entwickelt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Technisch möglich, aber oft unstrukturiert"}, {"text": "Nein", "correct": false, "because": "Analyse ist empfohlen, aber nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist es möglich, ein Programm zu entwickeln, das auf allen Betriebssystemen ohne Anpassung läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Plattformunterschiede erfordern Anpassungen"}, {"text": "Ja", "correct": false, "because": "Universelle Kompatibilität ist unrealistisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Programme in kompilierten Sprachen immer schneller als interpretierte Programme?', 2, '[{"text": "Nein", "correct": true, "because": "Geschwindigkeit hängt von Optimierung ab"}, {"text": "Ja", "correct": false, "because": "Interpretierte Programme können effizient sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Programme ohne Versionsverwaltung effektiv gewartet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Möglich, aber fehleranfällig und ineffizient"}, {"text": "Nein", "correct": false, "because": "Versionsverwaltung erleichtert, ist aber nicht zwingend"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprache wird oft für systemnahe Programmierung verwendet?', 3, '[{"text": "C", "correct": true, "because": "Bietet direkten Hardwarezugriff"}, {"text": "Python", "correct": false, "because": "Höhere Abstraktion"}, {"text": "JavaScript", "correct": false, "because": "Web-orientiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist das Hauptziel der Programmierung eines IT-Systems?', 2, '[{"text": "Erfüllung spezifischer Funktionen", "correct": true, "because": "Löst konkrete Probleme"}, {"text": "Maximierung der Codezeilen", "correct": false, "because": "Effizienz ist wichtiger"}, {"text": "Minimierung der Entwicklungszeit", "correct": false, "because": "Qualität steht im Vordergrund"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Entwicklungsmethode wird häufig für komplexe Programme genutzt?', 2, '[{"text": "Agile Entwicklung", "correct": true, "because": "Iterativ und flexibel"}, {"text": "Wasserfallmodell", "correct": false, "because": "Weniger anpassungsfähig"}, {"text": "Zufällige Programmierung", "correct": false, "because": "Unstrukturiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Fehler kann durch schlechte Programmierung entstehen?', 3, '[{"text": "Speicherlecks", "correct": true, "because": "Unfreigegebener Speicher"}, {"text": "Schnellere Ausführung", "correct": false, "because": "Fehler verlangsamen"}, {"text": "Kleinere Dateigröße", "correct": false, "because": "Nicht durch Fehler bedingt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Werkzeug hilft, Programmfehler systematisch zu finden?', 2, '[{"text": "Debugger", "correct": true, "because": "Ermöglicht schrittweise Analyse"}, {"text": "Texteditor", "correct": false, "because": "Nur zum Schreiben"}, {"text": "Compiler", "correct": false, "because": "Übersetzt, findet nicht alle Fehler"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Phasen umfasst die Entwicklung eines Programms typischerweise?', 4, '[{"text": "Anforderungsanalyse", "correct": true, "because": "Definiert Ziele"}, {"text": "Codierung", "correct": true, "because": "Umsetzung der Lösung"}, {"text": "Testen", "correct": true, "because": "Sichert Funktionalität"}, {"text": "Hardwareproduktion", "correct": false, "because": "Nicht Teil der Softwareentwicklung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Programmiersprachen sind für IT-Systeme relevant?', 3, '[{"text": "Java", "correct": true, "because": "Plattformunabhängig"}, {"text": "C++", "correct": true, "because": "Leistungsstark"}, {"text": "Python", "correct": true, "because": "Flexibel und einfach"}, {"text": "HTML", "correct": false, "because": "Markup, keine Programmierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen ein Programm hochwertig?', 4, '[{"text": "Wartbarkeit", "correct": true, "because": "Ermöglicht Anpassungen"}, {"text": "Effizienz", "correct": true, "because": "Ressourcenschonend"}, {"text": "Robustheit", "correct": true, "because": "Fehlerresistent"}, {"text": "Maximale Komplexität", "correct": false, "because": "Einfachheit ist oft besser"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen durch schlecht programmierte Software?', 3, '[{"text": "Sicherheitslücken", "correct": true, "because": "Angriffe möglich"}, {"text": "Performanceprobleme", "correct": true, "because": "Ineffizienter Code"}, {"text": "Datenverlust", "correct": true, "because": "Fehlerhafte Verarbeitung"}, {"text": "Kürzere Entwicklungszeit", "correct": false, "because": "Qualität kostet Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge unterstützen die Programmierung?', 3, '[{"text": "IDE", "correct": true, "because": "Integrierte Entwicklungsumgebung"}, {"text": "Versionsverwaltung", "correct": true, "because": "Verfolgt Änderungen"}, {"text": "Debugger", "correct": true, "because": "Findet Fehler"}, {"text": "Grafiktablet", "correct": false, "because": "Für Design, nicht Programmierung"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Programme müssen dokumentiert werden, um wartbar zu sein. b) Alle Programme sind automatisch plattformunabhängig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Dokumentation ja, Plattformabhängigkeit üblich"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Testen ist ein integraler Bestandteil der Programmierung. b) Programme müssen immer grafische Oberflächen haben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Testen ja, GUI optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Programm kann durch schlechten Code Speicherprobleme verursachen. b) Die Wahl der Programmiersprache ist irrelevant für die Leistung.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Speicher ja, Sprache beeinflusst Leistung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Modularer Code erleichtert die Wartung eines Programms. b) Programme sind immer schneller als Skripte.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Modularität ja, Geschwindigkeit variabel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Fehlerhafte Programme können Systemabstürze verursachen. b) Die Programmierung endet mit der Fertigstellung des Codes.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Abstürze ja, Testen und Wartung folgen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

